{
  "claims": [
    {
      "claim": "L'article 6 de la Constitution fédérale prévoit que les langues officielles de la Suisse sont l'allemand, le français, l'italien et le romanche, et qu'elles ont une valeur égale dans les rapports entre les autorités fédérales et les personnes qui parlent ces langues.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Pour prouver ses compétences linguistiques, une personne doit démontrer sa maîtrise d'une ou plusieurs de ces langues officielles.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Le niveau de compétence linguistique requis peut varier selon l'usage auquel il est destiné.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Pour prouver ses compétences linguistiques, une personne peut présenter des certificats de langue, des diplômes de fin d'études, des attestations d'employeur ou des résultats de tests de langue.",
      "verdict": "unverifiable"
    },
    {
      "claim": "L'autorité qui exige la preuve des compétences linguistiques peut procéder à une évaluation directe des compétences linguistiques de la personne, par exemple par un entretien oral.",
      "verdict": "unverifiable"
    },
    {
      "claim": "La preuve des compétences linguistiques doit être pertinente pour le contexte dans lequel elle est demandée.",
      "verdict": "unverifiable"
    }
  ],
